using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
int whole, digit; char dot; cin >> whole >> dot >> digit;
cout << digit << '.' << whole % 10 << whole / 10 % 10 << whole / 100 << '\n';
    return 0;
}
```

### 易错点

原数的整数部分保证为三位；输出各位，不要把小数后的部分重新合并成整数。

