using namespace std;
int main() {
    int s, v;
    cin >> s >> v;
    int walking = (s + v - 1) / v;
    int start = ((8 * 60 - walking - 10) % 1440 + 1440) % 1440;
    cout << setfill('0') << setw(2) << start / 60 << ':' << setw(2) << start % 60 << '\n';
}
```

### 易错点

先对步行时间向上取整；跨午夜时仍输出二十四小时制时刻。

