using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
int k; cin >> k;
int n = 0; double sum = 0;
while (sum <= k) { ++n; sum += 1.0 / n; }
cout << n << '\n';
    return 0;
}
```

### 易错点

条件是严格大于 $k$，等于时必须继续；先增加 $n$，再计算新项。

